final class ProgressionEngine
{
    public const COSMETICS=['theme-aurora'=>['Aurora palette',100],'theme-rose'=>['Rose palette',100],'keycap-outline'=>['Outline keycaps',75],'caret-beam'=>['Beam caret',60],'frame-orbit'=>['Orbit profile frame',125],'banner-dawn'=>['Dawn profile banner',150]];
    public static function xp(array $fact): int { $accuracy=$fact['attempts']?$fact['correctAttempts']/$fact['attempts']*100:0;$multiplier=$accuracy>=98?1:($accuracy>=95?.8:($accuracy>=90?.6:.3));return (int)round($fact['completedChars']*$multiplier*($fact['kind']==='game'?.4:1)); }
    private static function badges(): array { return [
        ['id'=>'characters-bronze','title'=>'First thousand','tier'=>'bronze','instruction'=>'Complete 1,000 correctly committed characters.','earnedBy'=>null],
        ['id'=>'characters-silver','title'=>'Steady hands','tier'=>'silver','instruction'=>'Complete 10,000 correctly committed characters.','earnedBy'=>null],
        ['id'=>'characters-gold','title'=>'Built by practice','tier'=>'gold','instruction'=>'Complete 100,000 correctly committed characters.','earnedBy'=>null],
        ['id'=>'accuracy-bronze','title'=>'Careful start','tier'=>'bronze','instruction'=>'Complete 100 characters with at least 98% input accuracy in one session.','earnedBy'=>null],
        ['id'=>'streak-silver','title'=>'A week of practice','tier'=>'silver','instruction'=>'Practice on seven consecutive calendar days.','earnedBy'=>null],
        ['id'=>'streak-gold','title'=>'A month of practice','tier'=>'gold','instruction'=>'Reach a 30-day practice streak.','earnedBy'=>null],
    ]; }
    private static function empty(string $owner,string $verification): array { return ['version'=>1,'ownerId'=>$owner,'verification'=>$verification,'xp'=>0,'level'=>1,'title'=>'Hunter','completedChars'=>0,'skills'=>['keys'=>[],'fingers'=>[],'bigrams'=>[],'trigrams'=>[]],'skillMaps'=>[],'skillScope'=>null,'streak'=>ProgressionCalendar::emptyStreak(),'quests'=>[],'ledger'=>[],'keys'=>0,'badges'=>self::badges(),'receipts'=>[],'commands'=>[],'cosmetics'=>[],'equipped'=>null,'weeklyXp'=>[],'gameXp'=>[]]; }
    public static function validate(array $fact,string $owner,string $verification): void
    {
        if(($fact['version']??null)!==1||($fact['ownerId']??null)!==$owner||($fact['verification']??null)!==$verification||!is_string($fact['id']??null)||$fact['id']===''||strlen($fact['id'])>128||!is_string($fact['payloadHash']??null)||$fact['payloadHash']===''||!in_array($fact['kind']??null,['practice','lesson','game','race'],true))throw new \InvalidArgumentException('Invalid progression receipt identity.');
        ProgressionCalendar::date($fact['at'],$fact['timeZone']);foreach(['completedChars','attempts','correctAttempts'] as $key)if(!is_int($fact[$key]??null)||$fact[$key]<0||$fact[$key]>1000000)throw new \InvalidArgumentException('Invalid progression counts.');
        if($fact['correctAttempts']>$fact['attempts']||$fact['completedChars']>$fact['correctAttempts']||!is_array($fact['skills'])||count($fact['skills'])>20000)throw new \InvalidArgumentException('Invalid canonical progression counts.');
        foreach(['lessonQualified','raceWin','personalBest30'] as $key)if(!is_bool($fact[$key]??null))throw new \InvalidArgumentException('Invalid qualification flags.');
        foreach($fact['skills'] as $sample){if(!in_array($sample['group']??null,['keys','fingers','bigrams','trigrams'],true)||!is_string($sample['key']??null)||$sample['key']===''||strlen(mb_convert_encoding($sample['key'],'UTF-16LE','UTF-8'))/2>100||!is_int($sample['n']??null)||$sample['n']<1||!is_int($sample['correct']??null)||$sample['correct']<0||$sample['correct']>$sample['n']||!is_int($sample['timingN']??null)||$sample['timingN']<0||$sample['timingN']>$sample['correct'])throw new \InvalidArgumentException('Invalid skill counts.');foreach(['weighted','ewma','lastLatency'] as $key){$number=$sample[$key]??null;if($number===null&&$key!=='weighted')continue;if(!(is_int($number)||is_float($number))||!is_finite((float)$number)||$number<0||$number>2000||($key!=='weighted'&&$number===0))throw new \InvalidArgumentException('Invalid skill timing.');}}
    }
    private static function award(array &$profile,array $entry): void { foreach($profile['ledger'] as $old)if($old['id']===$entry['id'])return;if($profile['keys']+$entry['delta']<0)throw new \InvalidArgumentException('Not enough Keys');$profile['ledger'][]=$entry;$profile['keys']+=$entry['delta']; }
    private static function reward(array &$p,string $id,int|float $at,int $delta,string $reason,string $source): void { self::award($p,['id'=>$id,'at'=>$at,'delta'=>$delta,'reason'=>$reason,'sourceId'=>$source]); }
    private static function quests(array &$profile,string $date): void { if(!array_filter($profile['quests'],fn($q)=>$q['date']===$date&&$q['template']!=='weekly'))array_push($profile['quests'],...ProgressionQuests::daily($profile['ownerId'],$date,$profile['skills'],false,$profile['skillScope']));if(!array_filter($profile['quests'],fn($q)=>$q['id']==='weekly:'.ProgressionCalendar::week($date)))$profile['quests'][]=ProgressionQuests::weekly($date); }
    private static function skills(array &$profile,array $contributions): void
    {
        foreach($contributions as $sample){$map=&$profile['skillMaps'][$profile['currentSkillScope']][$sample['group']];$old=$map[$sample['key']]??['n'=>0,'correct'=>0,'accuracy'=>.5,'speedMs'=>null,'latencyMs'=>null];$n=$old['n']+$sample['n'];$correct=$old['correct']+$sample['correct'];$speed=$sample['timingN']===0?$old['speedMs']:round($old['speedMs']===null?$sample['ewma']:(.8**$sample['timingN'])*$old['speedMs']+$sample['weighted'],3);$map[$sample['key']]=['n'=>$n,'correct'=>$correct,'accuracy'=>($correct+1)/($n+2),'speedMs'=>$speed,'latencyMs'=>$sample['lastLatency']??$old['latencyMs']];unset($map);}
    }
    private static function fact(array &$p,array $fact): void
    {
        $scope=$fact['skillScope']??'en|qwerty|keyboard|prose';$p['skillMaps'][$scope]??=['keys'=>[],'fingers'=>[],'bigrams'=>[],'trigrams'=>[]];$p['skillScope']??=$scope;$p['currentSkillScope']=$scope;$date=ProgressionCalendar::date($fact['at'],$p['streak']['zone']??$fact['timeZone']);self::quests($p,$date);$xp=self::xp($fact);
        if($fact['kind']==='game'){$xp=min($xp,max(0,1500-($p['gameXp'][$date]??0)));$p['gameXp'][$date]=($p['gameXp'][$date]??0)+$xp;}
        $p['xp']+=$xp;if($p['xp']>9007199254740991)throw new \InvalidArgumentException('XP limit exceeded');$week=ProgressionCalendar::week($date);$p['weeklyXp'][$week]=($p['weeklyXp'][$week]??0)+$xp;self::skills($p,$fact['skills']);$p['skills']=$p['skillMaps'][$p['skillScope']];$oldStreak=$p['streak']['count'];ProgressionCalendar::advance($p['streak'],$fact);
        foreach($p['quests'] as &$quest)if(ProgressionQuests::period($quest,$date)){$completed=$quest['completedBy'];ProgressionQuests::advance($quest,$fact);if(!$completed&&$quest['completedBy']){self::reward($p,'quest:'.$quest['id'],$fact['at'],$quest['reward'],'Quest completed',$fact['id']);ProgressionCalendar::freeze($p['streak'],'freeze:'.$quest['id'],'quest',$date);}}unset($quest);
        if($fact['lessonQualified'])self::reward($p,'lesson:'.$fact['id'],$fact['at'],10,'Qualified lesson',$fact['id']);
        if($fact['raceWin']&&$fact['verification']==='server-verified')self::reward($p,'race:'.$fact['id'],$fact['at'],15,'Verified race win',$fact['id']);
        if($fact['kind']==='game'&&$fact['completedChars']>=25){$daily=0;foreach($p['ledger'] as $entry)if($entry['reason']==='Arcade practice'&&ProgressionCalendar::date($entry['at'],$p['streak']['zone']??$fact['timeZone'])===$date)$daily+=$entry['delta'];$reward=min(20,5+(int)floor($fact['completedChars']/50),max(0,100-$daily));if($reward)self::reward($p,'game:'.$fact['id'],$fact['at'],$reward,'Arcade practice',$fact['id']);}
        foreach([7,30,100,365] as $milestone)if($oldStreak<$milestone&&$p['streak']['count']>=$milestone)self::reward($p,'streak:'.$milestone,$fact['at'],50,$milestone.'-day milestone',$fact['id']);
        $p['completedChars']+=$fact['completedChars'];$chars=$p['completedChars'];$predicates=[$chars>=1000,$chars>=10000,$chars>=100000,$fact['completedChars']>=100&&$fact['correctAttempts']/$fact['attempts']>=.98,$p['streak']['longest']>=7,$p['streak']['longest']>=30];foreach($p['badges'] as $index=>&$badge)if(!$badge['earnedBy']&&$predicates[$index])$badge['earnedBy']=$fact['id'];unset($badge);
    }
    private static function command(array &$p,array $command): void
    {
        $date=ProgressionCalendar::date($command['at'],$p['streak']['zone']??'UTC');self::quests($p,$date);$value=$command['value']??null;
        if($command['kind']==='reroll'){foreach($p['commands'] as $other)if($other['id']!==$command['id']&&$other['kind']==='reroll'&&$other['at']<=$command['at']&&ProgressionCalendar::date($other['at'],$p['streak']['zone']??'UTC')===$date)throw new \InvalidArgumentException('One free reroll per calendar day');foreach($p['quests'] as $q)if($q['date']===$date&&$q['template']!=='weekly'&&$q['completedBy'])throw new \InvalidArgumentException('Completed daily quests cannot be rerolled');$p['quests']=array_values(array_filter($p['quests'],fn($q)=>$q['date']!==$date||$q['template']==='weekly'));array_push($p['quests'],...ProgressionQuests::daily($p['ownerId'],$date,$p['skills'],true,$p['skillScope']));}
        elseif($command['kind']==='freeze-auto')$p['streak']['autoFreeze']=$value===true;
        elseif($command['kind']==='buy'){if($value==='streak-freeze'){if(!ProgressionCalendar::freeze($p['streak'],$command['id'],'purchase',$date))throw new \InvalidArgumentException('A purchased freeze is already available');self::reward($p,'buy:'.$command['id'],$command['at'],-75,'Streak freeze',$command['id']);}else{if(!is_string($value)||!isset(self::COSMETICS[$value])||in_array($value,$p['cosmetics'],true))throw new \InvalidArgumentException('Unknown or already owned cosmetic');[$label,$price]=self::COSMETICS[$value];self::reward($p,'buy:'.$command['id'],$command['at'],-$price,$label,$command['id']);$p['cosmetics'][]=$value;}}
        elseif($command['kind']==='equip'){if($value!==''&&!in_array($value,$p['cosmetics'],true))throw new \InvalidArgumentException('Own a cosmetic before equipping it');$p['equipped']=$value===''?null:$value;}
        else throw new \InvalidArgumentException('Unknown progression command');
    }
    public static function rebuild(string $owner,string $verification,array $receipts,array $commands=[]): array
    {
        $p=self::empty($owner,$verification);$ids=[];foreach($receipts as $fact){self::validate($fact,$owner,$verification);$serialized=json_encode($fact,JSON_THROW_ON_ERROR);if(isset($ids[$fact['id']])&&$ids[$fact['id']]!==$serialized)throw new \InvalidArgumentException('Conflicting progression receipt');if(!isset($ids[$fact['id']])){$ids[$fact['id']]=$serialized;$p['receipts'][]=$fact;}}
        $order=fn($a,$b)=>($a['at']<=>$b['at'])?:strcmp($a['id'],$b['id']);usort($p['receipts'],$order);$ids=[];foreach($commands as $command){if(!is_string($command['id']??null)||!$command['id']||strlen($command['id'])>128)throw new \InvalidArgumentException('Invalid command identity');ProgressionCalendar::date($command['at'],'UTC');$serialized=json_encode($command,JSON_THROW_ON_ERROR);if(isset($ids[$command['id']])&&$ids[$command['id']]!==$serialized)throw new \InvalidArgumentException('Conflicting progression command');if(!isset($ids[$command['id']])){$ids[$command['id']]=$serialized;$p['commands'][]=$command;}}usort($p['commands'],$order);
        $events=[];foreach($p['receipts'] as $fact)$events[]=['at'=>$fact['at'],'id'=>$fact['id'],'fact'=>$fact];foreach($p['commands'] as $command)$events[]=['at'=>$command['at'],'id'=>$command['id'],'command'=>$command];usort($events,$order);foreach($events as $event){if(isset($event['fact']))self::fact($p,$event['fact']);else self::command($p,$event['command']);}
        $level=min(100000,(int)floor(($p['xp']/100)**(1/1.35))+1);while($level<100000&&floor(100*$level**1.35)<=$p['xp'])$level++;while($level>1&&floor(100*($level-1)**1.35)>$p['xp'])$level--;$p['level']=$level;$titles=[1=>'Hunter',5=>'Pecker',10=>'Apprentice',20=>'Typist',30=>'Touch Typist',40=>'Fluent',55=>'Sonic',70=>'Thunder',85=>'Comet',100=>'Star',125=>'Galactic',150=>'Legendary',200=>'Mythic'];foreach($titles as $threshold=>$title)if($level>=$threshold)$p['title']=$title;
        unset($p['currentSkillScope']);foreach(['keys','fingers','bigrams','trigrams'] as $group)$p['skills'][$group]=(object)$p['skills'][$group];foreach($p['skillMaps'] as &$map){foreach(['keys','fingers','bigrams','trigrams'] as $group)$map[$group]=(object)$map[$group];}unset($map);$p['skillMaps']=(object)$p['skillMaps'];$p['weeklyXp']=(object)$p['weeklyXp'];$p['gameXp']=(object)$p['gameXp'];return $p;
    }
}
